var n="[QUIZ:",r="[QUIZ_RESULT:";function u(t,e){return`${n}${t}] ${e}`}function s(t,e){return`${r}${t}] Obtuvo ${e.toFixed(1)}/10`}function i(t){return t.startsWith(n)}function o(t){return t.startsWith(r)}function l(t){let e=t.match(/^\[QUIZ:(\d+)]\s*(.*)$/);return e?{quizId:+e[1],title:e[2]}:null}function a(t){let e=t.match(/^\[QUIZ_RESULT:(\d+)]\s*(.*)$/);return e?{quizId:+e[1],resultText:e[2]}:null}export{u as a,s as b,i as c,o as d,l as e,a as f};
